/// <summary>
/// AVA/WEN/2024/11/21   AVA_012426_HoursJournal
/// </summary>
public void fieldModifiedResourcePost()
{
    this.avaSetCategoryFromResource();
    next fieldModifiedResourcePost();
}

/// <summary>
/// AVA/WEN/2024/11/21   AVA_012426_HoursJournal
/// </summary>
public void avaSetCategoryFromResource()
{
    ProjCategory  categoryFromRes;

    ProjJournalTable projJournalTable = projJournalTable::find(projJournalTrans.journalId);

    if (projJournalTable.JournalType == ProjJournalType::Hour)
    {
        if (projJournalTrans.resource)
        {
            categoryFromRes = ProjCategory::findRecId(ResourceSetup::find(projJournalTrans.resource).DefaultTimeCategory);
            if (categoryFromRes)
            {
                projJournalTrans.CategoryId = categoryFromRes.CategoryId;
                projJournalTrans.TaxItemGroupId = categoryFromRes.TaxItemGroupId;
            }
        }
    }

}
